import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr00905Controller {
  @Get('/loan-statements')
  async listLoanStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const fromDate = String(query['fromDate'] ?? '');
    const toDate = String(query['toDate'] ?? '');
    const loanType = String(query['loanType'] ?? '');
    const partnerRaw = query['partnerId'];
    const hasPartner = partnerRaw !== undefined && partnerRaw !== null && String(partnerRaw) !== '';
    if (!DATE_PATTERN.test(fromDate) || !DATE_PATTERN.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일과 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (loanType !== 'BORROWING' && loanType !== 'LENDING') {
      throw new ApiError(400, 'VALIDATION_FAILED', '차입/대여 구분을 선택해 주세요.');
    }
    if (hasPartner && !/^\d+$/.test(String(partnerRaw))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '거래처 값이 올바르지 않습니다.');
    }
    const pageRaw = String(query['page'] ?? '0');
    const sizeRaw = String(query['size'] ?? String(DEFAULT_SIZE));
    if (!/^\d+$/.test(pageRaw) || !/^\d+$/.test(sizeRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const page = Number(pageRaw);
    const size = Math.min(Math.max(Number(sizeRaw), 1), MAX_SIZE);
    return transaction(async (db) => {
      const range = await db.query(
        'SELECT CAST(:fromDate AS date) > CAST(:toDate AS date) AS "invalid"',
        { fromDate, toDate },
      );
      if (range[0] && range[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
      }
      const params: Record<string, unknown> = {
        fromDate,
        toDate,
        loanType,
        partnerId: hasPartner ? String(partnerRaw) : null,
        limit: size,
        offset: page * size,
      };
      const where =
        'occurrence_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)' +
        ' AND loan_type = :loanType' +
        ' AND (CAST(:partnerId AS bigint) IS NULL OR partner_id = CAST(:partnerId AS bigint))';
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM loan_statement WHERE ' + where,
        params,
      );
      const items = await db.query(
        'SELECT loan_statement_id AS "loanStatementId",' +
          ' partner_id AS "partnerId",' +
          ' loan_type AS "loanType",' +
          ' occurrence_date AS "occurrenceDate",' +
          ' occurrence_amount AS "occurrenceAmount",' +
          ' repayment_amount AS "repaymentAmount",' +
          ' balance_amount AS "balanceAmount",' +
          ' is_voucher_processed AS "isVoucherProcessed"' +
          ' FROM loan_statement WHERE ' + where +
          ' ORDER BY occurrence_date DESC, loan_statement_id DESC' +
          ' LIMIT :limit OFFSET :offset',
        params,
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }

  @Post('/loan-statements/:loanStatementId/process-voucher')
  @HttpCode(200)
  async processLoanStatementVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const idText = req.params['loanStatementId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '명세 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT loan_statement_id AS "loanStatementId",' +
          ' occurrence_amount AS "occurrenceAmount",' +
          ' is_voucher_processed AS "isVoucherProcessed"' +
          ' FROM loan_statement WHERE loan_statement_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'LOAN_STATEMENT_NOT_FOUND', '명세 건을 찾을 수 없습니다.');
      }
      if (rows[0]['isVoucherProcessed'] === true) {
        throw new ApiError(409, 'LOAN_STATEMENT_ALREADY_PROCESSED', '이미 전표처리된 명세입니다.');
      }
      let voucherId: number | null = null;
      try {
        // 가정: 전표일자는 처리일, 원천 구분은 AUTO, 상태는 승인, 차대 합계는 발생금액
        const created = await db.query(
          'INSERT INTO journal_voucher (voucher_date, source_type, status, debit_total, credit_total, created_at, updated_at)' +
            ' VALUES (CAST(now() AS date), :sourceType, :status, :amount, :amount, now(), now())' +
            ' RETURNING journal_voucher_id AS "journalVoucherId"',
          { sourceType: 'AUTO', status: '승인', amount: rows[0]['occurrenceAmount'] },
        );
        if (created.length > 0) {
          voucherId = Number(created[0]['journalVoucherId']);
        }
      } catch (e) {
        voucherId = null;
      }
      if (voucherId === null) {
        throw new ApiError(422, 'VOUCHER_CREATION_FAILED', '전표 생성에 실패했습니다.');
      }
      const changed = await db.execute(
        'UPDATE loan_statement SET journal_voucher_id = :voucherId, is_voucher_processed = true, updated_at = now()' +
          ' WHERE loan_statement_id = CAST(:id AS bigint) AND is_voucher_processed = false',
        { voucherId, id: idText },
      );
      if (changed === 0) {
        throw new ApiError(409, 'LOAN_STATEMENT_ALREADY_PROCESSED', '이미 전표처리된 명세입니다.');
      }
      return {
        loanStatementId: Number(idText),
        journalVoucherId: voucherId,
        isVoucherProcessed: true,
      };
    });
  }
}

