import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr00905Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [loanType, setLoanType] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);

  const { data, error, loading, reload } = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page>('GET', '/loan-statements', role, undefined, { ...applied, page: pageNo, size: SIZE });
  }, [applied, pageNo, role]);

  const rows = data ? data.items : [];
  const pendingCount = rows.filter((r) => r.isVoucherProcessed !== true).length;

  const search = () => {
    if (!fromDate || !toDate || !loanType) {
      notify('조회 시작일, 조회 종료일, 차입/대여 구분을 입력해 주세요.');
      return;
    }
    setPageNo(0);
    setApplied({ fromDate, toDate, loanType, partnerId });
  };

  const reset = () => {
    setFromDate('');
    setToDate('');
    setLoanType('');
    setPartnerId('');
    setPageNo(0);
    setApplied(null);
  };

  const processVoucher = async () => {
    if (!target) {
      return;
    }
    await call('POST', `/loan-statements/${String(target.loanStatementId)}/process-voucher`, role);
    notify('전표처리했습니다.');
    setTarget(null);
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-6">
        <h2>조회 건수</h2>
        <Tiles items={[['조회 결과', <Num value={data ? data.total : 0} />]]} />
      </section>
      <section className="box span-6">
        <h2>처리 대기</h2>
        <Tiles items={[['현재 쪽 미처리', <Num value={pendingCount} />]]} />
      </section>
      <section className="box span-12">
        <h2>차입금·대여금 명세</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="차입/대여 구분" required>
            <Select
              value={loanType}
              onChange={setLoanType}
              options={[
                ['BORROWING', '차입금'],
                ['LENDING', '대여금'],
              ]}
            />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        <DataTable
          rows={rows}
          empty={applied ? '조회된 명세가 없습니다.' : '조회 조건을 입력하고 조회해 주세요.'}
          columns={[
            { key: 'partnerId', label: '거래처', render: (r) => <RefName table="partner" role={role} value={r.partnerId} /> },
            { key: 'loanType', label: '차입/대여 구분', render: (r) => <Badge value={r.loanType === 'BORROWING' ? '차입금' : '대여금'} /> },
            { key: 'occurrenceDate', label: '발생일자', render: (r) => <DateText value={r.occurrenceDate} /> },
            { key: 'occurrenceAmount', label: '발생금액', render: (r) => <Num value={r.occurrenceAmount} /> },
            { key: 'repaymentAmount', label: '상환금액', render: (r) => <Num value={r.repaymentAmount} /> },
            { key: 'balanceAmount', label: '잔액', render: (r) => <Num value={r.balanceAmount} /> },
            { key: 'isVoucherProcessed', label: '전표처리 여부', render: (r) => <Badge value={r.isVoucherProcessed === true ? '완료' : '대기'} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.isVoucherProcessed === true ? null : (
                  <button type="button" onClick={() => setTarget(r)}>
                    전표처리
                  </button>
                ),
            },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {target ? (
        <Drawer title="명세 전표처리" onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['거래처', <RefName table="partner" role={role} value={target.partnerId} />],
              ['차입/대여 구분', <Badge value={target.loanType === 'BORROWING' ? '차입금' : '대여금'} />],
              ['발생일자', <DateText value={target.occurrenceDate} />],
              ['발생금액', <Num value={target.occurrenceAmount} />],
              ['잔액', <Num value={target.balanceAmount} />],
            ]}
          />
          <Form onSubmit={processVoucher} submit="전표처리" note="선택한 명세 건으로 전표를 생성하고 전표처리 여부를 반영합니다." />
        </Drawer>
      ) : null}
    </div>
  );
}
